      html += '<h2 class="group-title">Waiting to arrive</h2>';
      ordered.forEach(function (item) {
        html += '<article class="card"><span class="badge ordered">Ordered</span><h3>' + esc(item.name) + '</h3><p>' + esc(item.orderedDate || '') + (item.orderedQty != null ? ' · ' + esc(formatCount(item.orderedQty, item)) : '') + '</p><button class="primary full" data-action="receive-open" data-id="' + esc(item.id) + '">Mark received</button></article>';
      });
